// PDL — Planificación behaviors (generated by scripts/build-css-index.mjs from
// design-system/registry/families.json). Pair it with css/family/temporal.
// Activates temporal; initPDL() activates every family.
import { initKanban } from "../temporal.js";

export function initFamily(options = {}) {
  const root = options.root ?? document;
  const instances = [
    initKanban(root),
  ];
  return {
    destroy() {
      for (const instance of instances.reverse()) instance?.destroy?.();
    }
  };
}
